'use client';
import { useState } from 'react';
import { api } from '@/lib/api';
import { toast } from 'sonner';
const categoryOptions = ['Classic Pizzas', 'Vegetarian Pizzas', 'Meat Lovers', 'Specialty / Gourmet Pizzas', 'Sides & Appetizers', 'Beverages & Desserts'];
export default function AddItem() {
  const [v, V] = useState({ itemName: '', category: 'Classic Pizzas', description: '', price: '', location: '' }), [images, setImages] = useState<string[]>([]), [busy, B] = useState(false), [uploading, U] = useState(false);
  function set(k: string, x: string) { V(o => ({ ...o, [k]: x })); }
  async function upload(files: FileList | null) {
    if (!files?.length) return; U(true);
    try { const uploaded: string[] = []; for (const file of Array.from(files).slice(0, 5)) { if (!file.type.startsWith('image/') || file.size > 5 * 1024 * 1024) throw new Error('Each image must be an image file under 5 MB'); const dataUrl = await new Promise<string>((resolve, reject) => { const reader = new FileReader(); reader.onload = () => resolve(String(reader.result)); reader.onerror = () => reject(new Error('Unable to read image')); reader.readAsDataURL(file); }); const result = await api<{ url: string }>('/upload', { method: 'POST', body: JSON.stringify({ image: dataUrl }) }); uploaded.push(result.url); } setImages(old => [...old, ...uploaded].slice(0, 5)); toast.success(`${uploaded.length} image(s) uploaded`); } catch (e: any) { toast.error(e.message); } finally { U(false); }
  }
  async function submit(e: React.FormEvent) { e.preventDefault(); B(true); try { await api('/menu', { method: 'POST', body: JSON.stringify({ ...v, price: Number(v.price), images }) }); toast.success('Menu item submitted for admin approval'); V({ itemName: '', category: 'Classic Pizzas', description: '', price: '', location: '' }); setImages([]); } catch (e: any) { toast.error(e.message); } finally { B(false); } }
  return <main className="section"><form className="card" onSubmit={submit} style={{ maxWidth: 760, margin: 'auto', display: 'grid', gap: 16 }}><p className="hero-kicker">MENU MANAGEMENT</p><h1 style={{ margin: 0 }}>Add Menu Item</h1><p className="muted">New items are saved as Pending and become public only after admin approval. Free plan supports up to 3 active items.</p><label>Item Name<input required minLength={2} maxLength={100} value={v.itemName} onChange={e => set('itemName', e.target.value)} /></label><label>Category<select value={v.category} onChange={e => set('category', e.target.value)}>{categoryOptions.map(x => <option key={x}>{x}</option>)}</select></label><label>Description<textarea required minLength={10} maxLength={1200} value={v.description} onChange={e => set('description', e.target.value)} /></label><div className="grid" style={{ gridTemplateColumns: '1fr 1fr' }}><label>Price (৳)<input type="number" min="1" step="0.01" required value={v.price} onChange={e => set('price', e.target.value)} /></label><label>Location (area / city)<input required value={v.location} onChange={e => set('location', e.target.value)} /></label></div><label>Item Images (required, up to 5)<input type="file" accept="image/*" multiple onChange={e => upload(e.target.files)} /></label>{uploading && <p className="muted">Uploading images to ImgBB…</p>}<div className="grid">{images.map((src, i) => <div key={src} style={{ position: 'relative' }}><img src={src} alt={`Uploaded menu image ${i + 1}`} className="menu-image" /><button type="button" className="btn secondary" style={{ marginTop: 6 }} onClick={() => setImages(old => old.filter(x => x !== src))}>Remove</button></div>)}</div><button className="btn" disabled={busy || uploading || !images.length}>{busy ? 'Submitting…' : 'Submit for Approval'}</button></form></main>;
}
